    def decorator(func):
        def wrapper(*args, **kwargs):
            # Introspect the function to see if it takes a tx parameter
            # Create a transaction context
            try:
                # Extract driver from the args (assume the first arg is the driver)
                driver = args[0]
            except Exception as e:
