def round_half_to_even(n):
    try:
        num = float(n)
    except (ValueError, TypeError):
        raise ValueError("n must be a number")

    if num == int(num):
        return int(num)

    lower = math.floor(num)
    upper = lower + 1
    distance_lower = num - lower
    distance_upper = upper - num

    if distance_lower < distance_upper:
        return lower
    elif distance_upper < distance_lower:
        return upper
    else:
        return lower if lower % 2 == 0 else upper

