    """ Dynamically create a Point subclass.
    """

    def __init__(self, srid, *values, **kwargs):
        self.srid = srid
        if srid not in srid_map:
            raise ValueError(f"SRID {srid} not found in srid_map")

        expected_fields = srid_map[srid]
        value_list = list(values)

        # Update value_list with keyword arguments if applicable,
        # ensuring correct order based on expected_fields
        for i, field in enumerate(expected_fields):
            if field in kwargs:
                if i < len(value_list):
                    # If both positional and keyword argument for the same field,
                    # we can prioritize kwargs or raise an error depending on strictness.
                    # Given typical monkeypatching contexts, overwriting is usually expected 
                    # or at least handled gracefully.
                    value_list[i] = kwargs.pop(field)

        # Fill in any remaining positional arguments
        for i, val in enumerate(values):
            if i < len(expected_fields):
                value_list[i] = val

        # Ensure we have exactly the right number of fields
        if len(value_list) < len(expected_fields):
            raise ValueError(f"Expected {len(expected_fields)} fields but got {len(value_list)}")

        for i, field in enumerate(expected_fields):
            setattr(self, field, value_list[i])

        if kwargs:
            raise ValueError(f"Unexpected keyword arguments: {list(kwargs.keys())}")

    cls = type(name, (object,), {
        '__init__': __init__,
        '__repr__': lambda self: f"{name}(srid={self.srid}, {', '.join(f"{f}={getattr(self, f)}" for f in srid_map[self.srid])})"
    })

    return cls

def point_type(name, fields, srid_map):
    class Point(object):
        __slots__ = ('_fields', '_srid_map')

        def __init__(self, values):
            self._fields = fields
            self._srid_map = srid_map
            self._values = values

        @property
        def values(self):
            return self._values

        def __repr__(self):
            field_names = [f.name for f in fields]
            values_str = ', '.join(f'{n}={str(v)}' for n, v in zip(field_names, self._values))
            return f'{name}({values_str})'

        def __eq__(self, other):
            if not isinstance(other, self.__class__):
                return NotImplemented
            return self._values == other._values

        def __hash__(self):
            return hash(tuple(self._values))

    # Set the class name dynamically
    Point.__name__ = name
    return Point

