def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison.

    Args:
        s (str): A version string like '1.2.3' or '1.2.3-alpha'.

    Returns:
        A tuple of integers representing the version numbers.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    # Remove leading/trailing whitespace
    s = s.strip()

    if not s:
        return ()

    # Extract only digits and dots, ignoring any non-numeric parts
    version_parts = []
    current_number = []

    for char in s:
        if char.isdigit():
            current_number.append(char)
        elif char == '.':
            if current_number:
                version_parts.append(int(''.join(current_number)))
                current_number = []
            else:
                version_parts.append(0)
        else:
            # Stop parsing at any non-numeric, non-dot character
            if current_number:
                version_parts.append(int(''.join(current_number)))
            break

    # Handle the last number
    if current_number:
        version_parts.append(int(''.join(current_number)))

    return tuple(version_parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.lstrip("vV").split(".")
    result = []
    for part in parts:
        if not part:
            continue
        if part.isdigit():
            result.append(int(part))
        else:
            # Extract leading digits if any
            i = 0
            digits = ""
            while i < len(part) and part[i].isdigit():
                digits += part[i]
                i += 1
            if digits:
                result.append(int(digits))
            else:
                result.append(0)
    return tuple(result)

def parse_version(s: str) -> tuple[int, ...]:
