    if not s or not isinstance(s, str):
        return ()
    s = s.strip()
    if not s:
        return ()
    # Split on dots, take the first part only (remove any suffix)
    s = s.split('.')
    result = []
    for part in s:
        # For each part, extract leading digits
        num = ''
        for ch in part:
            if ch.isdigit():
                num += ch
            else:
                break
        if not num:
            # if the part doesn't start with a digit, stop parsing
            break
        result.append(int(num))
    return tuple(result)

