def extostr(cls, e, max_level=30, max_path_level=5):
        import traceback
        import os
        import sys

        if not isinstance(e, Exception):
            raise TypeError("Input must be an instance of Exception or a subclass")

        # Get the traceback as a string
        tb = e.__cause__
        if tb:
            # Use __cause__ if available
            tb = tb.__traceback__

        # Get the traceback records
        if e.__traceback__ is not None:
            tb_records = traceback.extract_tb(e.__traceback__, limit=max_level)
        else:
            tb_records = []

        # Format the traceback
        tb_lines = []
        if tb_records:
            tb_lines.append("Traceback (most recent call last):" if len(tb_records) > 1 else "Traceback:")
        else:
            tb_lines.append("Traceback (most recent call last):")

        for frame in tb_records:
            filename = frame.filename
            # Truncate the path to max_path_level components
            if os.sep in filename:
                path_parts = filename.replace("\\", os.sep).split(os.sep)
                if len(path_parts) > max_path_level:
                    # Keep the last max_path_level parts
                    filename = os.sep.join(path_parts[-max_path_level:])
            tb_lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')

        # Append the exception itself
        if e.__class__.__name__ == 'Exception':
            exception_str = f"{type(e).__name__}: {str(e)}"
        else:
            exception_str = f"{type(e).__name__}: {str(e)}"

        tb_lines.append(exception_str)

        return "\n".join(tb_lines)

