def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    When ``output`` is not provided a **new** list (copy) of the normalized
    arguments is created and returned.
    """
    if sequence is None:
        raise TypeError("sequence is required")

    if not hasattr(sequence, '__iter__'):
        sequence = [sequence]

    if output is None:
        output = list(sequence)
    else:
        if not hasattr(output, '__iter__'):
            raise TypeError("output must be iterable or None")

    for index, element in enumerate(sequence):
        if hasattr(element, 'args'):
            # It is an Declaration (or object with 'args')
            for i, arg in enumerate(element.args):
                _normalizeargs(arg, output[index + i] if index + i < len(output) else None)

