def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        if bins.ndim != 1 or edges.ndim != 1:
            raise ValueError("Input 'bins' and 'edges' must be 1-D arrays.")
        if len(bins) == 0 or len(edges) == 0:
            raise ValueError("'bins' and 'edges' must not be empty.")
        if len(edges) < 2:
            raise ValueError("'edges' must contain at least two elements.")

        # Compute the width of each bin
        widths = np.diff(edges)

        # Compute the integral as the sum of the area of each bin
        integral = np.sum(bins * widths)

        return integral

    except Exception as e:
        raise ValueError(f"Invalid input: {e}")

