def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Check for root manifest
        root_manifest = self.fs.readtext(os.path.join(path, "manifests", "ocf_1.0", "root.txt").replace("\\", "/"))

        # Validate SHA-512 hashes
        for line in root_manifest.strip().splitlines():
            if not line.strip():
                continue
            parts = line.split()
            if len(parts) != 2:
                return False
            digest, relative_path = parts
            # Check digest format (SHA-512)
            if len(digest) != 128:
                return False
            try:
                int(digest, 16)
            except ValueError:
                return False
            # Check object exists
            full_path = os.path.join(path, relative_path).replace("\\", "/")
            if not self.fs.exists(full_path):
                return False
            # Verify hash
            with self.fs.open(full_path, 'rb') as f:
                file_hash = hashlib.sha512(f.read()).hexdigest()
                if file_hash != digest:
                    return False

        return True
    except Exception:
        return False

