        required_fields = {'name': str, 'items': list}
    elif self.spec_version == '2.0':
        required_fields = {'name': str, 'items': list, 'metadata': dict}
    else:
        # Default or unknown version check
        required_fields = {'name': str}

    for field, field_type in required_fields.items():
