def validate(self, inventory, extract_spec_version=False):
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")
    if extract_spec_version:
        spec_version = inventory.get('type', self.spec_version)
        if spec_version not in [1, 2, 3, '1', '2', '3']:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version
    errors = []
    if 'name' not in inventory:
        errors.append("Missing 'name' in inventory")
    if spec_version in [1, '1']:
        required_keys = ['name', 'version', 'packages']
        for key in required_keys:
            if key not in inventory:
                errors.append(f"Missing '{key}' for spec version 1")
        if 'version' in inventory and not isinstance(inventory['version'], int):
            errors.append("'version' must be an integer for spec version 1")
        if 'packages' in inventory and not isinstance(inventory['packages'], list):
            errors.append("'packages' must be a list for spec version 1")
    elif spec_version in [2, '2', 3, '3']:
        required_keys = ['name', 'version', 'packages']
        for key in required_keys:
            if key not in inventory:
                errors.append(f"Missing '{key}' for spec version 2")
        if 'version' in inventory and not isinstance(inventory['version'], str):
            errors.append("'version' must be a string for spec version 2")
        if 'packages' in inventory:
            if not isinstance(inventory['packages'], list):
                errors.append("'packages' must be a list for spec version 2")
            else:
                for package in inventory['packages']:
                    if not isinstance(package, dict):
                        errors.append("Each package must be a dictionary for spec version 2")
                        break
                    if 'name' not in package:
                        errors.append("Missing 'name' in package for spec version 2")
                        break
    if spec_version not in [1, '1', 2, '2', 3, '3']:
        errors.append(f"Invalid spec version: {spec_version}")
    if errors:
        raise ValueError("Invalid inventory: " + "; ".join(errors))

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files:
        return

    # Get all digests required by all manifest files
    required_digests = set()
    for file_info in manifest_files.values():
        if hasattr(file_info, 'with_digest') and file_info.with_digest:
            for digest in file_info.with_digest:
                required_digests.add(digest)

    # Check that all required digests are present in digests_used
    for digest in required_digests:
        if digest not in digests_used:
            raise Exception(f"Digest {digest} required but not present in digests_used")

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""

        # Extract the set of digests mentioned in the manifest files that are needed
        needed_digests = set()
        for file in manifest_files:
            for digest in file.get_required_digests():
                needed_digests.add(digest)

        # Check 1: All needed digests are present in digests_used
        missing_digests = needed_digests - set(digests_used)
        if missing_digests:
            return False, f"Missing digests: {missing_digests}"

        # Check 2: All digests in digests_used are used (i.e., are needed)
        unused_digests = set(digests_used) - needed_digests
        if unused_digests:
            return False, f"Unused digests: {unused_digests}"

        return True, "All required digests are present and used."

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        digests_needed = set().union(*[
            set(manifest_file.get('digests', [])) for manifest_file in manifest_files
        ])
        digests_missing = digests_needed - digests_used
        if digests_missing:
            raise Exception("Missing digests in digest usage list: %s" % digests_missing)
        for digest in digests_used:
            if digest not in digests_needed:
                raise Exception("Digest %s in digest usage list is not in the manifest" % digest)

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")
    # Assumption: self and prior have already been checked for internal consistency.
    # Perform validation logic to ensure prior is a valid prior version of self.
    # For example, check that item versions in prior are <= those in self, or keys are consistent.
    # Since the exact inventory structure isn't defined, we rely on a typical assumption:
    # prior must have the same item keys, and for each item, prior's version <= self's version.
    # Adjust based on expected InventoryValidator attributes (e.g., self.items, prior.items)

    # Let's assume InventoryValidator has an 'items' attribute which is a dict: {item_id: version}
    items_self = getattr(self, 'items', {})
    items_prior = getattr(prior, 'items', {})

    # Check that prior does not have items not in self
    for item_id in items_prior:
        if item_id not in items_self:
            raise ValueError(f"Item {item_id} in prior is not present in current inventory")

    # Check that versions in prior are <= versions in self
    for item_id, version_self in items_self.items():
        if item_id in items_prior:
            version_prior = items_prior[item_id]
            try:
                if version_prior > version_self:
                    raise ValueError(f"Version of item {item_id} in prior ({version_prior}) is greater than in current inventory ({version_self})")
            except TypeError:
