        # We need to adapt based on the structure of inventory
        # Based on typical usage patterns, let's assume file_entry is a dict with:
        # 'logical_path' or 'path' key, and 'content_files' key (a list)

        if not isinstance(file_entry, dict):
            continue

        # Try to get the logical path
        logical_path = file_entry.get('logical_path') or file_entry.get('path') or file_entry.get('destination')

        if logical_path is None:
