def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")
    if version not in inventory:
        raise KeyError(f"version '{version}' not found in inventory")

    version_entry = inventory[version]
    if not isinstance(version_entry, dict):
        raise ValueError(f"version entry for '{version}' must be a dictionary")

    # Assume version_entry has keys like:
    # {
    #   "logical_paths": { logical_path: "disks" },
    #   "duplication_map": { file: [duplicate_files] }
    # }
    logical_paths = version_entry.get("logical_paths", {})
    duplication_map = version_entry.get("duplication_map", {})

    if not isinstance(logical_paths, dict):
        raise ValueError("logical_paths must be a dictionary")
    if not isinstance(duplication_map, dict):
        raise ValueError("duplication_map must be a dictionary")

    path_to_files = {}
    for logical_path, files in logical_paths.items():
        file_set = set()
        if isinstance(files, (list, tuple, set)):
            primary_files = set(files)
        elif isinstance(files, str):
            primary_files = {files}
        else:
            primary_files = set()

        for f in primary_files:
            file_set.add(f)
            # Include duplicates from duplication_map if present
            if f in duplication_map:
                dups = duplication_map[f]
                if isinstance(dups, (list, tuple, set)):
                    file_set.update(dups)
                elif isinstance(dups, str):
                    file_set.add(dups)

        path_to_files[logical_path] = file_set

    return path_to_files

def get_logical_path_map(inventory, version):
    # Validate input parameters
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Check if version exists in inventory
    if version not in inventory:
        raise ValueError(f"Version '{version}' not found in inventory")

    # Initialize the result map
    logical_path_map = {}

    # Iterate through all versions in the inventory
    for ver, data in inventory.items():
        if not isinstance(data, dict):
            continue
        for logical_path, files in data.items():
            # Only consider paths that are lists/tuples of file references
            if not isinstance(files, (list, tuple)):
                continue

            # For each file reference in the list, add the logical_path to the map
            # Note: We include all versions' mappings, as per the docstring note
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()

            for file_ref in files:
                logical_path_map[logical_path].add(file_ref)

    return logical_path_map

