def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("Fixity 'files' must be a list")

    for file_entry in files:
        if not isinstance(file_entry, dict):
            raise ValueError("Each file entry must be a dictionary")

        if 'filename' not in file_entry:
            raise ValueError("Each file entry must contain a 'filename' key")

        filename = file_entry['filename']
        if not isinstance(filename, str):
            raise ValueError("File 'filename' must be a string")

        if filename not in manifest_files:
            raise ValueError(f"File {filename} not listed in manifest")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Define required keys for fixity
    required_keys = {"algorithm", "files"}

    # Check for required keys
    missing_keys = required_keys - set(fixity.keys())
    if missing_keys:
        raise ValueError(f"Fixity block is missing required keys: {missing_keys}")

    # Validate algorithm
    algorithm = fixity.get("algorithm")
    if not isinstance(algorithm, str):
        raise ValueError("Algorithm must be a string")
    if algorithm.lower() not in ["sha1", "sha256", "sha512", "md5"]:
        raise ValueError("Unsupported algorithm: {}".format(algorithm))

    # Validate files
    files = fixity.get("files")
    if not isinstance(files, dict):
        raise ValueError("Files must be a dictionary")

    # Check that each file is in manifest_files
    for file_path, checksum in files.items():
        if file_path not in manifest_files:
            raise ValueError("File not found in manifest: {}".format(file_path))
        if not isinstance(checksum, str):
            raise ValueError("Checksum must be a string for file: {}".format(file_path))
        # Optional: validate checksum format based on algorithm length
        expected_length = {
            "sha1": 40,
            "sha256": 64,
            "sha512": 128,
            "md5": 32
        }.get(algorithm.lower())
        if expected_length and len(checksum) != expected_length:
            raise ValueError("Checksum length mismatch for file: {}".format(file_path))

