        allowed_keys = {'file', 'hash', 'type'}  # Assuming 'type' is like 'sha1', 'md5', etc.

        # Validate structure of each fixity entry
        for file_referenced, message_and_hash in fixity.items():
            # Check if file is in manifest_files
            if not manifest_files:
                # If manifest_files is None or empty, we can still check structure
                pass
            elif file_referenced not in manifest_files:
                raise ValueError(f"File '{file_referenced}' is not listed in the manifest.")

            # message_and_hash should be a dict with keys 'message' and 'hash'
            if not isinstance(message_and_hash, dict):
                raise ValueError(f"Fixity entry for '{file_referenced}' must be a dictionary with 'message' and 'hash' keys.")

            required_keys = {'message', 'hash'}
            if not required_keys.issubset(message_and_hash.keys()):
                raise ValueError(f"Fixity entry for '{file_referenced}' must contain 'message' and 'hash' keys.")

            # Check that message is a string or None/empty
            message = message_and_hash['message']
            if not isinstance(message, str) and message is not None:
                raise ValueError(f"Message for file '{file_referenced}' in fixity must be a string or None.")

            # Check hash is a non-empty string
            hash_val = message_and_hash['hash']
            if not isinstance(hash_val, str) or not hash_val:
                raise ValueError(f"Hash for file '{file_referenced}' in fixity must be a non-empty string.")

def validate_fixity(self, fixity, manifest_files):
    # Check if fixity is a dictionary
    if not isinstance(fixity, dict):
        raise TypeError("Fixity must be a dictionary")

    # Ensure 'path_list' exists and is a list
    if 'path_list' not in fixity:
        raise ValueError("Fixity must contain 'path_list'")

    path_list = fixity['path_list']
    if not isinstance(path_list, list):
        raise TypeError("Fixity 'path_list' must be a list")

    # Ensure 'checklist' exists and is a list
    if 'checklist' not in fixity:
        raise ValueError("Fixity must contain 'checklist'")

    checklist = fixity['checklist']
    if not isinstance(checklist, list):
        raise TypeError("Fixity 'checklist' must be a list")

    # Ensure each item in checklist has 'path' and 'digest' and 'digest_type'
    for index, entry in enumerate(checklist):
        if not isinstance(entry, dict):
            raise TypeError(f"Checklist item at index {index} must be a dictionary")
        for key in ['path', 'digest', 'digest_type']:
            if key not in entry:
                raise ValueError(f"Checklist item at index {index} must contain '{key}'")

    # Convert manifest_files to a set for faster lookup
    manifest_set = set(manifest_files) if manifest_files else set()

    # Check that only files listed in manifest are referenced
    for entry in checklist:
        path = entry['path']
        if path not in manifest_set:
            raise ValueError(f"Path {path} not found in manifest files")

    return True

