def _group_files_by_xml_filename(source, xmls, files):
    import os
    import zipfile
    from collections import defaultdict

    # Group files into lists per xml basename
    groups = defaultdict(list)
    for f in files:
        # Normalize the path for processing
        base = f.lower() if isinstance(f, str) else None
        if not base:
            continue
        # Determine if this is an XML file
        if base.endswith('.xml'):
            # Skip the xml file itself when grouping non-xml files
            continue
        # Determine if it's a sidecar xml (naming convention: *.pr.xmi, *.pr.xsd, *.pr.xml, etc.)
        # Look for the xml file basename (without extension) that matches a known xml file in xmls
        try:
            stem, ext = os.path.splitext(base)
        except Exception:
            stem, ext = base, ''
        # Some sidecars have multiple extensions like .pr.xmi -> stem = 'name.pr'
        # We'll check known xml basenames from the xmls dict keys (lowercased)
        # Map xml keys to lowercased names for matching
        xml_lower_map = {}
        for full_xml in xmls:
            norm_key = full_xml.lower()
            # Normalize to basename without extension for matching sidecars
            xml_name, _ = os.path.splitext(norm_key)
            xml_lower_map[xml_name] = full_xml

        preferred = None
        # Try exact stem match
        if stem in xml_lower_map:
            preferred = xml_lower_map[stem]
        else:
            # Try matching stem that ends with '.pr' etc. by removing known suffixes
            # Common suffixes: .pr.xmi, .pr.xsd, .pr.xml
            # We'll remove trailing two-level extension if possible
            # e.g., 'name.pr.xmi' -> remove '.xmi' -> 'name.pr'
            parts = stem.split('.')
            if len(parts) >= 2:
                # candidate with second last removed
                cand = '.'.join(parts[:-2])
                if cand in xml_lower_map:
                    preferred = xml_lower_map[cand]
                else:
                    # maybe three part names like 'a.b.c'
                    if len(parts) >= 3:
                        cand3 = '.'.join(parts[:-3])
                        if cand3 in xml_lower_map:
                            preferred = xml_lower_map[cand3]

        if preferred is not None:
            groups[preferred].append(f)
        else:
            # If no xml matches, ignore or put in 'unknown'
            groups['__unknown__'].append(f)

    # Create Package objects and return
    # We need to import Package class; if not available, fallback to simple dict
    try:
        # Try to import Package from typical module path if available at runtime
        # This is a best-effort; in many environments, the class might be importable
        # We'll attempt to import from any reasonable relative or absolute path
        try:
            from .package import Package  # relative import
        except Exception:
            try:
                import __main__ as m
                Package = getattr(m, 'Package', None)
                if Package is None:
                    # Attempt dynamic import from the module where this function is defined?
                    # This is tricky without more context. Fallback to a simple class
                    raise Exception()
            except Exception:
                # Define a minimal Package class inline if not found
                class Package:
                    def __init__(self, source, xml, files):
                        self.source = source
                        self.xml = xml
                        self.files = list(files)

        # Build packages
        result = {}
        for xml_full, fl in groups.items():
            if xml_full == '__unknown__':
                continue
            result[xml_full] = Package(source, xml_full, fl)
        return result
    except Exception:
        # Fallback: return a simple dict mapping xml to list of files
        result = {xml_full: {'source': source, 'xml': xml_full, 'files': list(fls)} for xml_full, fls in groups.items() if xml_full != '__unknown__'}
        return result

