                if basename not in packages:
                    packages[basename] = {}
                # Store each file's data by its full name
                packages[basename][name] = {
                    'tag': root.tag,
                    'attrib': root.attrib,
                    'children': []
                }
                for child in root:
                    packages[basename][name]['children'].append({
                        'tag': child.tag,
                        'attrib': child.attrib,
