def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Assuming self is a valid object that has a __repr__ or similar
    if debug:
        # If debug, include the repr
        return f"{self.__class__.__name__}(value={self!r})" + '\n' * max(0, indent) 
    else:
        # Otherwise, just return a clean representation
        return f"{self.__class__.__name__}" + '\n' * max(0, indent)

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        # We have to handle different types of objects
        if isinstance(self, dict):
            if not self:
                return "{}"
            indent_str = "  " * (indent + 1)
            lines = ["{"]
            items = list(self.items())
            for i, (key, value) in enumerate(items):
                key_str = str(key)
                if i < len(items) - 1:
                    lines.append(f"{indent_str}{key_str}: {value.pretty(indent + 1, debug)},")
                else:
                    lines.append(f"{indent_str}{key_str}: {value.pretty(indent + 1, debug)}")
            if debug:
                lines.append(f"{'  ' * indent}Debug mode enabled")
            lines.append("  " * indent + "}")
            return "\n".join(lines)
        elif isinstance(self, list):
            if not self:
                return "[]"
            indent_str = "  " * (indent + 1)
            lines = ["["]
            for i, item in enumerate(self):
                if i < len(self) - 1:
                    lines.append(f"{indent_str}{item.pretty(indent + 1, debug)},")
                else:
                    lines.append(f"{indent_str}{item.pretty(indent + 1, debug)}")
            if debug:
                lines.append(f"{'  ' * indent}List length: {len(self)}")
            lines.append("  " * indent + "]")
            return "\n".join(lines)
        elif isinstance(self, str):
            return f"'{self}'"
        elif isinstance(self, (int, float, bool)):
            return str(self)
        else:
            # Fallback for other types
            return str(self)

def pretty(self, indent=0, debug=False):
    indent_str = "    " * indent
    result = []
    for key, value in self.__dict__.items():
        if key.startswith('_') and not debug:
            continue
        if isinstance(value, dict):
            value_str = "{" + ", ".join([f"{inner_key}: {inner_value}" for inner_key, inner_value in value.items()]) + "}"
            result.append(f"{indent_str}  {key}: {value_str}")
        elif isinstance(value, list):
            if len(value) == 0:
                value_str = "[]"
            else:
                value_lines = [f"{indent_str}    {item}" for item in value]
                value_str = "[\n" + ",\n".join(value_lines) + f"\n{indent_str}  ]"
            result.append(f"{indent_str}  {key}: {value_str}")
        else:
            result.append(f"{indent_str}  {key}: {value}")
    return "{\n" + ",\n".join(result) + f"\n{indent_str}}" if result else f"{indent_str}{{}}"

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        if not hasattr(self, "__repr__"):
            raise AttributeError("Object must have a __repr__ method")

        lines = []
        base_indent = "  " * indent
        lines.append(f"{base_indent}{{'type': {type(self).__name__}, 'id': {id(self)},")
        if debug:
            try:
                attrs = self.__dict__
                for key, value in attrs.items():
                    if len(lines) >= 3:  # limit number of debug attributes to print
                        break
                    lines.append(f"{base_indent}  '{key}': {repr(value)},")
            except Exception as e:
                lines.append(f"{base_indent}  'debug error': {str(e)}")
        lines.append(f"{base_indent}}}")
        return "\n".join(lines)

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """

        def _absorb(a, b):
            a_terms = a.args if hasattr(a, 'args') else (a,)
            b_terms = b.args if hasattr(b, 'args') else (b,)

            # Check for absorption: A & (A | B) -> A
            if isinstance(a, And) and isinstance(b, Or):
                for term_a in a_terms:
                    if any(term_a == term_b for term_b in b_terms):
                        return a
            if isinstance(b, And) and isinstance(a, Or):
                for term_b in b_terms:
                    if any(term_b == term_a for term_a in a_terms):
                        return b

            # Check for negative absorption: A & (~A | B) -> A & B
            if isinstance(a, And) and isinstance(b, Or):
                for term_a in a_terms:
                    neg_term_a = Not(term_a)
                    if any(neg_term_a == term_b for term_b in b_terms):
                        new_b = Or(*[term_b for term_b in b_terms if term_b != neg_term_a])
                        if new_b is S.true:
                            return a
                        else:
                            return And(a, new_b)
            if isinstance(b, And) and isinstance(a, Or):
                for term_b in b_terms:
                    neg_term_b = Not(term_b)
                    if any(neg_term_b == term_a for term_a in a_terms):
                        new_a = Or(*[term_a for term_a in a_terms if term_a != neg_term_b])
                        if new_a is S.true:
                            return b
                        else:
                            return And(new_a, b)

            return None

        result = []
        for i, expr_i in enumerate(args):
            for j, expr_j in enumerate(args):
                if i == j:
                    continue

                absorbed = _absorb(expr_i, expr_j)
                if absorbed is not None:
                    if expr_i is not absorbed and expr_j is not absorbed:
                        if expr_i in result:
                            result.remove(expr_i)
                        if expr_j in result:
                            result.remove(expr_j)
                        if absorbed not in result:
                            result.append(absorbed)

            if expr_i not in result:
                result.append(expr_i)

        return result

