def normalized(self):
        total_usages = self.years * 12 * 30 + self.months * 30 + self.days + self.hours / 24.0 + self.minutes / 60.0 * 24 + self.seconds / 3600.0 * 24 + self.microseconds / 1000000.0 / 3600.0 * 24
        years = self.years
        months = self.months
        days = int(total_usages)
        hours_total = int((total_usages - days) * 24)
        hours = 0
        minutes = 0
        seconds = 0
        microseconds = 0
        if self.days != 0:
            days = self.days
            hours_total = self.hours
            minutes = self.minutes
            seconds = self.seconds
            microseconds = self.microseconds
        elif self.hours != 0:
            hours_total = self.hours
            minutes = self.minutes
            seconds = self.seconds
            microseconds = self.microseconds
        elif self.minutes != 0:
            minutes = self.minutes
            seconds = self.seconds
            microseconds = self.microseconds
        elif self.seconds != 0:
            seconds = self.seconds
            microseconds = self.microseconds
        elif self.microseconds != 0:
            microseconds = self.microseconds

        # normalize hours, minutes, seconds, microseconds
        if hours_total >= 24:
            days += hours_total // 24
            hours_total = hours_total % 24
        if hours_total < 0:
            days += (hours_total + 1) // 24  # careful with negative
            hours_total = hours_total % 24
            if hours_total < 0:
                hours_total += 24
        hours = hours_total

        if minutes >= 60:
            hours += minutes // 60
            minutes = minutes % 60
        if minutes < 0:
            hours += (minutes + 1) // 60
            minutes = minutes % 60
            if minutes < 0:
                minutes += 60

        if seconds >= 60:
            minutes += seconds // 60
            seconds = seconds % 60
        if seconds < 0:
            minutes += (seconds + 1) // 60
            seconds = seconds % 60
            if seconds < 0:
                seconds += 60

        if microseconds >= 1000000:
            seconds += microseconds // 1000000
            microseconds = microseconds % 1000000
        if microseconds < 0:
            seconds += (microseconds + 1) // 1000000
            microseconds = microseconds % 1000000
            if microseconds < 0:
                microseconds += 1000000

        # normalize months, days (simple approximation: 1 month = 30 days)
        if days >= 30:
            months += days // 30
            days = days % 30
        if days < 0:
            months += (days + 1) // 30
            days = days % 30
            if days < 0:
                days += 30

        if months >= 12:
            years += months // 12
            months = months % 12
        if months < 0:
            years += (months + 1) // 12
            months = months % 12
            if months < 0:
                months += 12

        return relativedelta(years=years, months=months, days=days, hours=hours,
                             minutes=minutes, seconds=seconds, microseconds=microseconds)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """

    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if isinstance(result, tuple):
            return tuple(item.encode('utf-8') if isinstance(item, str) else item for item in result)
        elif isinstance(result, str):
            return result.encode('utf-8')
        else:
            return result

    return wrapper

