def render(pieces, style):
    """Render the given version pieces into the requested style."""
    prerendered = pieces.get("closest-tag")
    if prerendered:
        return prerendered

    style_pieces = style.replace("-", "_")
    if not style_pieces:
        return pieces["version"]

    # Construct the version string based on the given style and pieces.
    if style == "pep440":
        # PEP440 compliant style.
        if pieces.get("error"):
            # If we encountered an error earlier, return the version with an error marker.
            version = "%s.portion1" % pieces["version"] if "version" in pieces else ""
            return version + ".dev0"

        # Check for distance
        if pieces.get("distance") is not None:
            # There is a distance, use it.
            if pieces.get("dirty"):
                # Dirty state
                version = pieces.get("version", "")
                version += ".dev%d" % pieces["distance"] + "+d"
            else:
                # Not dirty
                version = pieces.get("version", "")
                version += ".dev%d" % pieces["distance"]
        else:
            # No distance, just the tag
            if pieces.get("dirty"):
                # Dirty state
                version = pieces.get("version", "") + ".post0"
            else:
                # Not dirty
                version = pieces.get("version", "")

        return version

    elif style == "git-describe":
        # git-describe style.
        if pieces.get("error"):
            return pieces.get("version", "")
        else:
            if pieces.get("distance") is not None:
                return pieces["version"] + "-g" + pieces["short"] + ("+" if pieces.get("dirty") else "")
            else:
                return pieces.get("tag", pieces.get("short", ""))
    elif style == "python-dateutil":
        # Python dateutil style
        if pieces.get("error"):
            return pieces.get("version", "")
        else:
            return pieces.get("version", "")
    else:
        # Default style
        if pieces.get("error"):
            return pieces.get("version", "")
        else:
            if pieces.get("distance") is not None:
                return pieces["version"] + "-" + pieces["short"] + ("-" if not pieces.get("dirty") else "")
            else:
                return pieces.get("tag", pieces.get("short", ""))

