    # Convert to a single string for shell execution
    cmd_str = ' '.join(cmd_list)

    # Prepare environment
    if env is None:
        env = os.environ.copy()

    if verbose:
        print(f"Running: {cmd_str}")

    try:
        if hide_stderr:
            # Redirect stderr to devnull
            with open(os.devnull, 'w') as devnull:
                result = subprocess.run(cmd_str, shell=True, stdout=subprocess.PIPE, stderr=devnull, cwd=cwd, env=env, text=True)
                if result.returncode != 0:
                    raise subprocess.CalledProcessError(result.returncode, cmd_str, output=result.stdout)
                return result.stdout
        else:
            result = subprocess.run(cmd_str, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env, text=True)
            if result.returncode != 0:
                if verbose:
                    print(f"Command failed with return code {result.returncode}: {result.stderr}")
                raise subprocess.CalledProcessError(result.returncode, cmd_str, output=result.stdout, stderr=result.stderr)
            if verbose and result.stdout:
                print(result.stdout, end='')
            return result.stdout
    except Exception as e:
        if verbose:
            print(f"Error executing command: {e}")
        raise

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not hasattr(vcs, 'vcs_handlers'):
        vcs.vcs_handlers = {}
    vcs.vcs_handlers[method] = method.name
    return method

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, (list, tuple, set, frozenset)):
        raise TypeError("vcs param must be an iterable")
    if not callable(method):
        raise TypeError("method param must be callable")
    for v in vcs:
        method.vcs_handlers = getattr(method, 'vcs_handlers', set())
        method.vcs_handlers.add(v)
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    try:
        for obj in self._objects:
            num_objects += 1
            if validate_objects and self._validate_object_structure(obj):
                if check_digests and self._check_object_digest(obj):
                    good_objects += 1
                elif check_digests and not self._check_object_digest(obj):
                    if show_warnings:
                        self._warning(f"Digest mismatch for object: {obj.id()}")
            elif validate_objects and not self._validate_object_structure(obj):
                if show_warnings:
                    self._warning(f"Invalid object structure: {obj.id()}")
            elif not validate_objects and check_digests and self._check_object_digest(obj):
                good_objects += 1
            elif not validate_objects:
                good_objects += 1
    except Exception as e:
        self._warning(f"Error during hierarchy validation: {e}")
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        num_objects = 0
        good_objects = 0
        if not validate_objects:
            return num_objects, good_objects

        objects = self.storage_root.get_objects()

        for obj_id, obj in objects.items():
            num_objects += 1
            try:
                if self.storage_root.validate_object(obj_id, check_digests):
                    good_objects += 1
                elif show_warnings:
                    print(f"Warning: Object {obj_id} is invalid")
            except Exception as e:
                if show_warnings:
                    print(f"Error validating object {obj_id}: {e}")

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    # Initialize counter for individual object validation errors or warnings
    for member in self.members:
        if member.is_valid():
            num_objects += 1
            if validate_objects and member.validate():
                if check_digests and member.digest_matches():
                    good_objects += 1
                else:
                    if show_warnings:
                        self._warn(f"Digest mismatch for object {member.name}")
            elif show_warnings:
                self._warn(f"Validation failed for object {member.name}")
        else:
            if show_warnings:
                self._warn(f"Object {member.name} is not valid")
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Start from the root object
    if not hasattr(self, 'root') or self.root is None:
        if show_warnings:
            print("Warning: No root object available for validation.")
        return 0, 0

    stack = [self.root]
    visited = set()

    while stack:
        current_object = stack.pop()

        if current_object is None or id(current_object) in visited:
            continue

        visited.add(id(current_object))
        num_objects += 1

        is_valid = True

        if validate_objects:
            # Check if object has required attributes/methods
            if not hasattr(current_object, 'get_children') or not hasattr(current_object, 'digest'):
                is_valid = False

        if check_digests and is_valid:
            try:
                # Verify the digest of the current object
                current_digest = current_object.digest()
                if not current_digest:
                    is_valid = False
            except Exception:
                is_valid = False
                if show_warnings:
                    print(f"Warning: Error calculating digest for object {id(current_object)}")

        if is_valid:
            good_objects += 1
        else:
            if show_warnings:
                print(f"Warning: Invalid object detected at {id(current_object)}")

        # Get children and add to the stack if validation is not fully failed
        try:
            children = current_object.get_children()
            for child in children:
                if child is not None and id(child) not in visited:
                    stack.append(child)
        except Exception:
            if show_warnings:
                print(f"Warning: Error retrieving children for object {id(current_object)}")

    return num_objects, good_objects

def next_version(version):
    if not isinstance(version, str):
        raise ValueError("version must be a string")
    if not version:
        raise ValueError("version cannot be empty")
    # Split into numeric parts
    parts = version.split('.')
    if len(parts) == 0:
        raise ValueError("Invalid version format")
    # Track if any part had leading zeros
    zero_prefixed = any(part != '0' and part.startswith('0') for part in parts)
    # Convert parts to integers
    try:
        int_parts = [int(part) for part in parts]
    except ValueError:
        raise ValueError("Invalid version format: parts must be non-negative integers")
    if any(part < 0 for part in int_parts):
        raise ValueError("Invalid version: parts must be non-negative")
    # Increment the last part
    int_parts[-1] += 1
    # Restore leading zeros if the version was zero-prefixed (apply to all parts)
    if zero_prefixed:
        # Determine the max length seen in the original (excluding all-zero strings like '0000')
        max_len = 0
        for part in parts:
            if part != '0':
                max_len = max(max_len, len(part))
            # Treat '0' as length 1 for padding purposes when other parts are longer
            elif max_len == 0:
                max_len = 1
        # If no non-zero parts found (e.g., '0.0'), use minimum length 1
        if max_len == 0:
            max_len = 1
        # Ensure we don't have a part shorter than the original length if it was part of zero-prefixed sequence
        # But since we know zero_prefixed is True, at least one part had leading zeros.
        # Re-evaluate: The rule says "deals with both zero-prefixed and non-zero prefixed versions".
        # Typical interpretation: If input has leading zeros (e.g., '00.01'), output uses same width.
        # Let's refine: use the length of the part that had the leading zero? Or max length of all?
        # Standard versioning convention for zero-prefixed: maintain the width of the stack!
        # Let's stick to global max length, which is common.
        formatted = []
        for part in int_parts:
            # If it's the last part, we just incremented it.
            formatted.append(str(part).zfill(max_len))
        return '.'.join(formatted)
    else:
        return '.'.join(map(str, int_parts))

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        if self.inventory_map is None:
            raise Exception("No root inventory found or parsed.")

        for version_dir in version_dirs:
            version_path = os.path.join(self.root, version_dir)
            if not os.path.isdir(version_path):
                continue
            self.validate_version_directory(version_dir, version_path)

        # TODO: If we check each inventory against its parent, we should not have to
        # compare all versions. It should be equivalent, but it's an assumption.

        # Validate each version inventory for accurate content digests.
        for version_name, inventory_map in self.versions.items():
            dirname = version_name
            if dirname == "":
                dirname = self.root_inventory.name
            self.validate_inventory_content(inventory_map, dirname)

    def validate_version_directory(self, version_name, version_path):
        """Parse the version's inventory and compare it against its parent."""
        inventory_path = os.path.join(version_path, "inventory.sig")
        inventory_obj = None

        if not os.path.exists(inventory_path):
            W("No inventory found to validate version {0}".format(version_name))
            self.validate_version_public_key = None
            return

        try:
            data = self._get_data(inventory_path)
            inventory_obj = self._make_base_object(data)
        except Exception as e:
            W("Cannot parse {0}: {1}".format(inventory_path, e))
            self.validate_version_public_key = None
            return

        # Make a copy as a way of maining the hashes of self.versions[inventory.public_key]
        tmp_map = copy.copy(inventory_obj.map)

        self._verify_inventory_content(
            inventory_obj.map,
            inventory_obj.public_key,
            self.validate_version_public_key,
            version_path
        )

        if not self.versions.get(inventory_obj.public_key, None):
            self.versions[inventory_obj.public_key] = dict()

        self.versions[inventory_obj.public_key].update(tmp_map)

    def validate_inventory_content(self, inventory_map, dirname=""):
        """Validate the content digests saved in the inventory map."""
        path_infos = []
        # Recursively build a path for each path from the inventory.
        for path_name in inventory_map.keys():
            path_infos.append(os.path.join(dirname, path_name))

        # Verify that all paths in the inventory have valid files.
        if not self._check_paths_exist(path_infos):
            W("Missing files in {0}".format(dirname))
            return

        # Get the content digests for all the paths from the python files.
        # Sidestep issues calculating private key hashes by totally ignoring them.
        for path_name, path_info in inventory_map.items():
            if path_info.is_private_key:
                continue
            path_abspath = os.path.join(dirname, path_name)
            self.verify_file(path_name, path_abspath, path_info)

    def verify_file(self, path_name, path_abspath, path_info):
        """Verify a single file in the inventory by comparing content digest."""
        try:
            calc_hash_info = self._calculate_content_digest(path_abspath)
        except Exception as e:
            W("Cannot use root inventory to validate version inventory path {0}: {1}".format(path_name, e))
            return

        if calc_hash_info == path_info:
            return
        # If the digest doesn't match, and it is not in the root inventory, it's a problem.
        W("Content digest for {0} does not match the value in inventory {1}".format(path_name, path_info))
        # If we are reading a version inventtory and this content digest is not according to the root inventory,
        # it may be an error, but it could also be that it was updated out-of-band in the version.
        #
        # Check to see whether this path is in the root inventory, but different from what is in this inventory.
        if not self.root_inventory or not self.root_inventory.map:
            return
        root_digest_info = self.root_inventory.lookup(path_name)
        if not root_digest_info:
            W("File {0} not found in root inventory".format(path_name))
            return
        if root_digest_info != calc_hash_info:
            # root variable holds paths to each version of the content
            W("Content digest for {0} does not match the value in the root inventory".format(path_name))
            return
        # The file content matches the root inventory but not the version inventory.
        # Add it to the self.versions
        self._add_unverified_digest(path_name, root_digest_info)

    def _calculate_content_digest(self, path):
        """Calculate the content digest of a file."""
        with open(path, 'rb') as f:
            data = f.read()
        return self._hash_data(data)

    def _check_paths_exist(self, paths):
        """Check if all the paths in the list exist."""
        for path in paths:
            if not os.path.exists(path):
                return False
        return True

    def _make_base_object(self, data):
        """Stub for making an inventory object from data. Just return a dummy object."""
        class DummyInventory:
            def __init__(self, data):
                self.data = data
                self.map = data.get('paths', {})
                self.public_key = data.get('pubkey', 'unknown')
                self.name = 'inventory.sig'
        return DummyInventory(data if isinstance(data, dict) else {})

    def _get_data(self, path):
        """Stub for getting data from a path."""
        # For pure unit tests or mocked setups, just produce a minimal dict.
        # In real code, you'd read the file JSON/relaxedSIG data.
        return {"paths": {}}

    def _hash_data(self, data):
        """Calculate a simple hash (stub)."""
        import hashlib
        return {"pathinfo": hashlib.sha256(data).hexdigest()}

    def _verify_inventory_content(self, inventory_map, pub_key, current_pub, version_path):
        """Stub for verifying the inventory object against the crypto signatures."""
        return True

    def _add_unverified_digest(self, path_name, digest_info):
        """Record a digest that needs later verification."""
        if not hasattr(self, 'unverified'):
            self.unverified = {}
        self.unverified[path_name] = digest_info

def validate_version_inventories(self, version_dirs):
    """
    Validates that each version directory contains an inventory file, and records
    content digests that differ from those in the root inventory for later content checks.

    Args:
        version_dirs (list): A list of version directory names, ordered by version sequence.

    Returns:
        dict: A mapping from version directory name to the list of content digests
              that are different from the root inventory (or None if no discrepancies).
              If a version directory is missing an inventory file, the value will be False
              to indicate the missing inventory.
    """
    result = {}
    root_inventory = getattr(self, 'root_inventory', None)
    root_digests = None
    if root_inventory:
        root_digests = {}
        for item in root_inventory.contents:
            # Prepare a set of digests for the filename from the root inventory
            # item.filename gives the path, item.digests is a list of digest strings
            root_digests[item.filename] = set(item.digests)
    for dir_name in version_dirs:
        inventory = self.get_inventory(dir_name)
        if inventory is None:
            result[dir_name] = False
        else:
            different_digests = []
            for item in inventory.contents:
                if root_digests is not None:
                    fdigests = root_digests.get(item.filename)
                    if fdigests is not None:
                        # Check if any of the item's digests are not in root
                        found_match = False
                        for dg in item.digests:
                            if dg in fdigests:
                                found_match = True
                                break
                        if not found_match:
                            different_digests.append(item)
            result[dir_name] = different_digests
    return result

def validate_version_inventories(self, version_dirs):
    inventories = {}
