def find_path_type(path):
    import os

    try:
        # Check if path exists
        if not os.path.exists(path):
            return "error: path does not exist"

        # Check if it's a root (OCFL Storage Root) - typically has 0/root.spec
        if os.path.isfile(os.path.join(path, "0", "root.spec")):
            return "root"

        # Check if it's an object (OCFL Object) - has 0/object.yaml
        if os.path.isfile(os.path.join(path, "0", "object.yaml")):
            return "object"

        # Check if it's a file
        if os.path.isfile(path):
            return "file"

        # If it's a directory but doesn't match OCFL patterns
        if os.path.isdir(path):
            # Check if it has any 0/* files that might be inventory
            if os.path.exists(os.path.join(path, "0")):
                # Check if 0 directory contains any files that look like inventory
                zero_dir = os.path.join(path, "0")
                if os.path.isdir(zero_dir):
                    for item in os.listdir(zero_dir):
                        if item.endswith(('.yaml', '.yml')):
                            return "object"
            return "unknown directory type"

        # Fallback
        return "unknown path type"

    except Exception as e:
        return "error: {}".format(str(e))

def find_path_type(path):
    import os
    try:
        if not os.path.exists(path):
            return 'error: path does not exist'
        if os.path.isfile(path):
            # Check if it's a file, might be an inventory (e.g., 0=inventory.json)
            basename = os.path.basename(path)
            if basename.startswith('0='):
                return 'file'
            return 'file'
        if os.path.isdir(path):
            # Check for 0= directory entries
            try:
                entries = os.listdir(path)
            except PermissionError:
                return 'error: permission denied'
            Has 0= directory entries
            for entry in entries:
                if entry.startswith('0='):
                    # Look at the 0= directory
                    return 'object'
            # No 0= entries found, check if it looks like a root (has spec version, etc.)
            # A Storage Root typically contains a 'spec-version' file or similar
            # But the docstring says "looks at 0=* files to determine type"
            # If no 0=* files, it might be a root or just a directory
            # Check for 'spec-version' or 'README.md' or 'storage.json'
            if 'spec-version' in entries:
                return 'root'
            if 'storage.json' in entries:
                return 'root'
            if 'README.md' in entries:
                return 'root'
            return 'directory'
        return 'unknown'
    except Exception as e:
        return f'error: {str(e)}'

