def deep_merge_nodes(nodes):
    if not nodes:
        return []

    from ruamel.yaml.nodes import ScalarNode, MappingNode, SequenceNode

    key_to_values = {}
    key_order = []

    for key, value in nodes:
        if key not in key_to_values:
            key_to_values[key] = []
            key_order.append(key)
        key_to_values[key].append(value)

    result = []
    for key in key_order:
        values = key_to_values[key]
        if len(values) == 1:
            result.append((key, values[0]))
        else:
            all_mappings = all(isinstance(v, MappingNode) for v in values)
            if all_mappings:
                merged_value = MappingNode(tag='tag:yaml.org,2002:map', value=[])
                for v in values:
                    merged_value.value = deep_merge_nodes(merged_value.value + v.value)
                result.append((key, merged_value))
            else:
                result.append((key, values[-1]))

    return result

def deep_merge_nodes(nodes):
    if not nodes:
        return nodes

    merged_dict = {}
    for key_node, value_node in nodes:
        key_value = getattr(key_node, 'value', key_node)
        if key_value in merged_dict:
            if (_is_mapping(value_node) and _is_mapping(merged_dict[key_value])):
                merged_dict[key_value] = MappingNode(
                    tag=value_node.tag,
                    value=deep_merge_nodes(merged_dict[key_value].value + value_node.value)
                )
            else:
                merged_dict[key_value] = value_node
        else:
            merged_dict[key_value] = value_node

    return [
        (
            (MappingNode(tag=key.tag, value=key.value) if isinstance(key, MappingNode) else ScalarNode(tag=key.tag, value=key.value)),
            (MappingNode(tag=val.tag, value=val.value) if isinstance(val, MappingNode) else ScalarNode(tag=val.tag, value=val.value))
        )
        for key, val in merged_dict.items()
    ]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode
    merged = {}
    key_order = []
    for key, value in nodes:
        if not isinstance(key, ScalarNode):
            continue
        key_hash = (key.tag, key.value)
        if key_hash not in merged:
            key_order.append(key_hash)
            merged[key_hash] = (key, value)
        else:
            old_key, old_value = merged[key_hash]
            if isinstance(old_value, MappingNode) and isinstance(value, MappingNode):
                deep_merged_value = deep_merge_nodes(old_value.value + value.value)
                merged[key_hash] = (key, MappingNode(tag=value.tag, value=deep_merged_value))
            else:
                merged[key_hash] = (key, value)
    return [merged[key_hash] for key_hash in key_order]

def deep_merge_nodes(nodes):
    merged = {}
    for key, value in nodes:
        if key.value in merged:
            existing = merged[key.value]
            if isinstance(existing, MappingNode) and isinstance(value, MappingNode):
                merged[key.value] = MappingNode(
                    tag=existing.tag,
                    value=deep_merge_nodes(list(existing.value) + list(value.value))
                )
            else:
                merged[key.value] = value
        else:
            merged[key.value] = value
    return [(k, v) for k, v in merged.items()]

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    parser = argparse.ArgumentParser()

    # Check if there are no arguments to parse
    if len(arguments) == 0:
        # Use default command-line arguments from sys.argv[1:]
        return parser.parse_args()

    # Convert the arguments to a list if it's a tuple
    args = list(arguments)

    # If the first argument is a string and has no spaces, it might be a command name
    # In many scripts, the first argument is the script name itself
    # We can optionally remove it if it looks like the script path (but be careful)
    # For safety, we just parse all arguments as provided

    try:
        return parser.parse_args(args)
    except SystemExit:
        # Re-raise SystemExit or handle appropriately
        if args:
            # If there was an issue, we can re-raise or handle
            raise
        else:
            raise

def parse_arguments(*arguments):
    parser = argparse.ArgumentParser(description='Parse command-line arguments')
    for arg in arguments:
        if arg.startswith('-'):
            parser.add_argument(arg)
    args = parser.parse_args(list(arguments))
    return args

def parser_flags(parser):
    flags = []
    for action in parser._actions:
