def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed = {}
    remaining = list(unparsed_arguments)
    for name, parser in subparsers.items():
        # The parser may be None (skip), or an argparse.ArgumentParser instance
        if parser is None:
            continue
        try:
            # Ask the parser to parse the full argument list (no need to 'consume' here;
            # we will filter out known options in order to keep the remainder for other parsers).
            # We only want the parsed namespace; argparse turns anything it doesn't know
            # into an error, so call parse_args with the same full list.
            try:
                namespace = parser.parse_args(remaining)
            except SystemExit:
                # Don't raise; this parser couldn't parse the args (e.g., missing required options).
                # Treat as not applicable for this subparser. Skip.
                continue
            # Now build the set of known options/actions to determine which input tokens were
            # 'claimed' by this parser, so we can remove them from the shared remaining list.
            claimed = set()
            # Collect long option strings (including 'options' metadata) and positional action names
            known_opt_strings = set()
            for action in parser._actions:
                # _action has .option_strings like ['--repo', '-r'] and .dest for positional actions
                if hasattr(action, 'option_strings'):
                    for s in action.option_strings:
                        known_opt_strings.add(s)
                # positional actions do not have option_strings; we do not consume positional argument
                # texts generically because we don't reliably map values back to positions. To keep
                # behavior predictable and avoid over-removal, we only remove recognized *option*
                # tokens (strings that start with options declared by the parser), and any values that
                # directly follow those options (we will handle via scan below).
            # Walk through the remaining args, and mark option strings and their associated values
            i = 0
            n = len(remaining)
            # To know how many values each option expects (nargs), map option string(s) to the corresponding action
            opt_to_action = {}
            for action in parser._actions:
                if hasattr(action, 'option_strings'):
                    for s in action.option_strings:
                        opt_to_action[s] = action
            while i < n:
                token = remaining[i]
                if token in known_opt_strings and token in opt_to_action:
                    claimed.add(i)
                    # Determine how many following tokens are consumed by this option
                    act = opt_to_action[token]
                    nargs = getattr(act, 'nargs', None)
                    consume = 0
                    if nargs is None:
                        # behavior based on required/delimiter is complex; safest: treat as 1 value unless it's a flag
                        # argparse: if nargs is None, default is 1 unless the option is a flag (append/count?)
                        # For simplicity, consume 1 value unless the next token is an option-like string
                        if i + 1 < n and not (remaining[i+1].startswith('-') and remaining[i+1] != '-'):
                            consume = 1
                        else:
                            consume = 0
                    else:
                        if isinstance(nargs, int):
                            consume = nargs
                        # OPTIONS/STORE_DATE etc can be strings like '+/-' or 'A*'; to avoid over-consumption,
                        # for list-like nargs we consume only if the next token is a bare value. But without full
                        # parser state this is risky, so limit to exact ints for automatic removal.
                        else:
                            # for '*', '+', '?' or other special nargs, do not automatically consume
                            consume = 0
                    # mark the consumed value indices
                    for k in range(1, consume + 1):
                        idx = i + k
                        if idx < n:
                            claimed.add(idx)
                    i += 1 + consume
                else:
                    i += 1
            # Remove claimed indices from remaining to ensure later subparsers see a reduced list.
            remaining = [v for idx, v in enumerate(remaining) if idx not in claimed]
            parsed[name] = namespace
        except Exception:
            # Could not parse with this subparser; skip it
            continue
    return parsed, remaining

