def deep_merge_nodes(nodes):
    """
    Deep merge any node values corresponding to duplicate keys and return the result.
    """
    import collections
    from ruamel.yaml.nodes import ScalarNode, MappingNode, SequenceNode

    def get_key(node):
        # Use the value of the key node as the identifier
        if isinstance(node, ScalarNode):
            return node.value
        else:
            # For non-scalar keys, try to convert to string form
            return str(node.value) if hasattr(node, 'value') else id(node)

    def is_mapping_node(node):
        return isinstance(node, MappingNode)

    def deep_merge_mappings(mapping1, mapping2):
        """
        Deep merge two MappingNodes.
        mapping2's values override mapping1's for scalar keys, and mapping nodes are recursively merged.
        """
        merged = MappingNode(tag=mapping1.tag, value=[], flow_style=mapping1.flow_style if hasattr(mapping1, 'flow_style') else None)

        # First, add all entries from mapping1
        key_map = {}
        for key_node, value_node in mapping1.value:
            key_str = get_key(key_node)
            key_map[key_str] = (key_node, value_node)
            merged.value.append((key_node, value_node))

        for key_node, value_node in mapping2.value:
            key_str = get_key(key_node)
            if key_str in key_map:
                existing_key_node, existing_value_node = key_map[key_str]
                if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                    # Recursively merge mappings
                    new_value_node = deep_merge_mappings(existing_value_node, value_node)
                    # Replace the value in merged
                    for i, (k, v) in enumerate(merged.value):
                        if get_key(k) == key_str:
                            merged.value[i] = (k, new_value_node)
                            break
                else:
                    # Override with the new value
                    for i, (k, v) in enumerate(merged.value):
                        if get_key(k) == key_str:
                            merged.value[i] = (k, value_node)
                            break
            else:
                # Add new entry
                merged.value.append((key_node, value_node))
                key_map[key_str] = (key_node, value_node)

        return merged

    merged = []
    key_map = {}  # Maps key string to index in merged list

    for key_node, value_node in nodes:
        key_str = get_key(key_node)
        if key_str in key_map:
            idx = key_map[key_str]
            existing_value_node = merged[idx][1]
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                # Deep merge the two mappings
                new_value_node = deep_merge_mappings(existing_value_node, value_node)
                merged[idx] = (key_node, new_value_node)
            else:
                # Override
                merged[idx] = (key_node, value_node)
        else:
            key_map[key_str] = len(merged)
            merged.append((key_node, value_node))

    return merged

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    if not nodes:
        return nodes

    from ruamel.yaml.nodes import ScalarNode, MappingNode, SequenceNode

    merged_dict = {}
    for key, value in nodes:
        # Use a consistent key representation
        if isinstance(key, ScalarNode):
            key_repr = key.value
        else:
            # Fallback: use the node itself if it's not a ScalarNode
            key_repr = key

        if key_repr not in merged_dict:
            merged_dict[key_repr] = value
        else:
            existing_value = merged_dict[key_repr]
            # Deep merge logic
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                # Recursively merge the mapping nodes
                merged_mapping_value = deep_merge_nodes(existing_value.value + value.value)
                # Create a new MappingNode with the merged value
                new_mapping = MappingNode(existing_value.tag, merged_mapping_value)
                new_mapping.ca = existing_value.ca  # copy custom attributes if needed
                merged_dict[key_repr] = new_mapping
            else:
                # Last value wins for non-MappingNode
                merged_dict[key_repr] = value

    # Convert back to list of tuples
    result = []
    for key_repr, value in merged_dict.items():
        # Find the original ScalarNode for this key
        # We need to preserve the original key node
        for key, _ in nodes:
            if isinstance(key, ScalarNode) and key.value == key_repr:
                result.append((key, value))
                break
            elif key is not None and not isinstance(key, ScalarNode):
                # For non-ScalarNode keys, we might need to find the exact match
                if key_repr is key:
                    result.append((key, value))
                    break

    return result

