    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    # If url_args is not a dictionary, convert it or handle appropriately
    if not isinstance(url_args, dict):
        url_args = dict(url_args) if hasattr(url_args, 'keys') else {}

    # Find all placeholders in the format {key} and replace with values from url_args
