    def replace_match(match):
        key = match.group(1)
        if key in url_args:
            return _quote_if_needed(str(url_args[key]))
        else:
            return match.group(0)

    def _quote_if_needed(value):
        # If it looks like it needs URL quoting, do so
        from urllib.parse import quote_from_bytes, quote
        try:
            # URL encode special characters
            return quote(value, safe='')
        except Exception:
            return value

    # Pattern to match {key} placeholders
    pattern = r'\{([^}]+)\}'
    result = re.sub(pattern, replace_match, url)

