def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number == 0:
        result = alphabet[0]
    else:
        if number < 0:
            raise ValueError("Number must be non-negative")

        base = len(alphabet)
        if base <= 1:
            raise ValueError("Alphabet must have at least 2 characters")

        # Convert number to digits in the given base
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        result = ''.join(digits[::-1])

    if padding is not None:
        if len(result) > padding:
            return result
        else:
            return result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    base = len(alphabet)

    if number == 0:
        digits = [alphabet[0]]
    else:
        if number < 0:
            raise ValueError("Negative numbers are not supported")
        digits = []
        while number > 0:
            number, remainder = divmod(number, base)
            digits.append(alphabet[remainder])
        digits.reverse()

    result = ''.join(digits)

    if padding is not None and len(result) < padding:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        result = alphabet[0]
    else:
        negative = number < 0
        number = abs(number)
        digits = []
        while number > 0:
            number, digit = divmod(number, len(alphabet))
            digits.append(alphabet[digit])
        result = ''.join(reversed(digits))
        if negative:
            result = '-' + result

    if padding is not None and len(result) < padding:
        result = result.zfill(padding)

    return result

