        elif unit_lower in ["millisecond", "milliseconds"]:
            kwargs = {"milliseconds": num}
        elif unit_lower in ["week", "weeks"]:
            kwargs = {"weeks": num}
        else:
            raise ValueError(f"Invalid unit of time: {unit}")

        return datetime.timedelta(**kwargs)

    except ValueError:
        raise
    except Exception as e:
        raise ValueError(f"Could not parse frequency: {frequency}") from e

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency)}")

    frequency = frequency.strip().lower()
    if not frequency:
        raise ValueError("Frequency string cannot be empty")

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{parts[0]}'")

    unit = parts[1]
    if not unit:
        raise ValueError("Unit cannot be empty in frequency")

    unit_map = {
        "microsecond": "microseconds",
        "microseconds": "microseconds",
        "millisecond": "milliseconds",
        "milliseconds": "milliseconds",
        "second": "seconds",
        "seconds": "seconds",
        "minute": "minutes",
        "minutes": "minutes",
        "hour": "hours",
        "hours": "hours",
        "day": "days",
        "days": "days",
        "week": "weeks",
        "weeks": "weeks"
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit: '{unit}'")

    key = unit_map[unit]
    if number < 0:
        raise ValueError(f"Frequency number must be non-negative: '{frequency}'")

    return datetime.timedelta(**{key: number})

