def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        return False

    # Normalize the host to lowercase
    host = host.lower().strip()

    # Check common localhost aliases
    localhost_aliases = {
        'localhost', 
        '127.0.0.1',
        '[::1]',
        '::1',
        '0.0.0.0'
    }

    if host in localhost_aliases:
        return True

    # Try to resolve the hostname to an IP address
    try:
        # Try to get all address resolution results
        addr_info = socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM)

        for family, socktype, proto, canonname, sockaddr in addr_info:
            # For IPv4, sockaddr is (ip, port)
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip == '127.0.0.1' or ip.startswith('127.'):
                    return True
            # For IPv6, sockaddr is (ip, port, flowinfo, scopeid)
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == '::1':
                    return True
    except (socket.gaierror, socket.error):
        # If we can't resolve the host, it's not localhost
        return False

    return False

