def _resolve_string(matcher):
    #
    # matcher: str 1n the format "name" or "name:default"
    # If the matcher is not a string, raise TypeError
    # If the environment variable exists, return its value
    # If the environment variable does not exist and a default is provided, return the default
    # Otherwise (no env var, no default), raise ValueError
    if not isinstance(matcher, str):
        raise TypeError(f"Expected a string matcher, got {type(matcher)}")

    # Split on the first colon if present
    if ':' in matcher:
        name, default = matcher.split(':', 1)
    else:
        name = matcher
        default = None

    # Get the value from the environment
    env_value = os.environ.get(name)
    if env_value is not None:
        return env_value
    elif default is not None:
        return default
    else:
        raise ValueError(f"Environment variable '${name}' is not defined and no default value provided")

def _resolve_string(matcher):
    if not isinstance(matcher, str):
        raise TypeError("matcher must be a string")

    # Split the matcher on the first '=' if present to separate name and default value
    if '=' in matcher:
        name, default_value = matcher.split('=', 1)
    else:
        name = matcher
        default_value = None

    # Get the value from the environment
    env_value = os.environ.get(name)

    # If the environment variable is not defined and no default value is provided, raise an error
    if env_value is None and default_value is None:
        raise ValueError(f"Environment variable '{name}' is not defined and no default value provided")

    # Return the environment variable value if defined, otherwise return the default value
    return env_value if env_value is not None else default_value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    if not image_href or not isinstance(image_href, str):
        raise ValueError("Image href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Failed to parse image href: {e}")

    # Use secure flag if parsed.scheme is not 'http' (covers https, ftps, etc.)
    use_ssl = parsed.scheme != 'http'

    # Extract netloc
    if not parsed.netloc:
        raise ValueError(f"Invalid image href: missing netloc in {image_href}")
    else:
        netloc = parsed.netloc

    # Extract image_id from path
    if parsed.path == "/" or not parsed.path:
        empty_id = f"{netloc}-"
        return empty_id, netloc, use_ssl
    else:
        image_id = parsed.path.lstrip('/').replace('/', '-')
        return image_id, netloc, use_ssl

