    """Call the given command(s)."""
    import subprocess
    if isinstance(commands, list):
        p = None
        for c in commands:
            for a in args:
                c.append(str(a))
            p = subprocess.Popen(c, cwd=cwd, env=env,
                                 stdout=subprocess.PIPE,
                                 stderr=subprocess.PIPE if hide_stderr else None)
        retcode = p.wait()
    else:
        p = subprocess.Popen(commands + list(args), cwd=cwd, env=env,
                             stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE if hide_stderr else None)
        retcode = p.wait()
    stderr = ''
    if retcode:
        stderr = p.stderr.read()
        if hasattr(stderr, 'decode'):
            stderr = stderr.decode()
    if verbose:
        print(stderr)
    if retcode:
        raise subprocess.CalledProcessError(retcode, ' '.join(str(x) for x in commands))
    return retcode

