def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json

    import os

    import logging
    configurations = {}
    errors = []
    if config_filenames is None:
        return {}, [logging.LogRecord("load_configurations", logging.ERROR, "load_configurations", 0, "config_filenames cannot be None", None, None)]
    if not isinstance(config_filenames, (list, tuple)):
        return {}, [logging.LogRecord("load_configurations", logging.ERROR, "load_configurations", 0, "config_filenames must be a list or tuple", None, None)]
    for filename in config_filenames:
        try:
            if not filename or not isinstance(filename, str):
                error_record = logging.LogRecord("load_configurations", logging.ERROR, "load_configurations", 0, "Invalid filename: %s" % str(filename), None, None)
                errors.append(error_record)
                continue

            with open(filename, 'r') as f:
                content = f.read()

            if resolve_env:
                for key, value in (overrides.items() if overrides else {}):
                    placeholder = os.environ.get(key, value)
                    content = content.replace('{"' + key + '"}', placeholder)

            try:
                config = json.loads(content)
                if not isinstance(config, dict):
                    raise ValueError("Configuration must be a JSON object")
            except (json.JSONDecodeError, ValueError) as e:
                error_record = logging.LogRecord("load_configurations", logging.ERROR, "load_configurations", 0, "Failed to parse %s: %s" % (filename, str(e)), None, None)
                errors.append(error_record)
                continue

            if overrides:
                for key, value in overrides.items():
                    placeholder = os.environ.get(key, value)
                    if key in config:
                        if isinstance(config[key], str):
                            config[key] = placeholder
                        else:
                            config[key] = value

            configurations[filename] = config
        except Exception as e:
            error_record = logging.LogRecord("load_configurations", logging.ERROR, "load_configurations", 0, "Unexpected error reading %s: %s" % (str(filename), str(e)), None, None)
            errors.append(error_record)
    return configurations, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import json
    import yaml
    import logging

    # create an empty dict to store parsed configs
    configs = {}

    # create an empty list to store log records
    log_records = []

    # define a helper function to handle logging of records
    def log_record(log_name, level, message, record_name=None):
        record = logging.LogRecord(
            name=log_name,
            level=level,
            pathname='',
            lineno=0,
            msg=message,
            args=(),
            exc_info=None
        )
        if record_name:
            record.name = record_name
        log_records.append(record)

    # iterate over each filename
    for filename in config_filenames:
        try:
            # determine the file extension
            _, file_extension = os.path.splitext(filename)
            file_extension = file_extension.lower()

            # open and read the file
            with open(filename, 'r') as f:
                file_content = f.read()

            # parse based on extension
            if file_extension == '.json':
                config_dict = json.loads(file_content)
            elif file_extension in ['.yaml', '.yml']:
                config_dict = yaml.safe_load(file_content)
            else:
                raise ValueError(f"Unsupported file format: {file_extension}")

            # if overrides is provided, merge overrides into config_dict
            if overrides:
                config_dict = {**config_dict, **overrides}

            # resolve environment variables if resolve_env is True
            if resolve_env:
                def replace_env_vars(obj):
                    if isinstance(obj, str):
                        def replace_match(match):
                            var_name = match.group(1)
                            return os.environ.get(var_name, match.group(0))
                        import re
                        pattern = re.compile(r'\$\{([^}]+)\}')
                        return pattern.sub(replace_match, obj)
                    elif isinstance(obj, list):
                        return [replace_env_vars(item) for item in obj]
                    elif isinstance(obj, dict):
                        return {k: replace_env_vars(v) for k, v in obj.items()}
                    else:
                        return obj

                config_dict = replace_env_vars(config_dict)

            configs[filename] = config_dict

        except (IOError, OSError) as e:
            log_record('load_configurations', logging.ERROR, f"Failed to read file {filename}: {str(e)}", filename)
        except (json.JSONDecodeError, yaml.YAMLError) as e:
            log_record('load_configurations', logging.ERROR, f"Failed to parse file {filename}: {str(e)}", filename)
        except ValueError as e:
            log_record('load_configurations', logging.ERROR, f"Error in file {filename}: {str(e)}", filename)
        except Exception as e:
            log_record('load_configurations', logging.ERROR, f"Unexpected error processing file {filename}: {str(e)}", filename)

    return configs, log_records

