    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if len(bases) == 0:
        raise TypeError("bases must contain at least one item")

    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        metaclass = object

    for base in bases:
        base_mc = type(base)
        if not issubclass(metaclass, base_mc) and not issubclass(base_mc, metaclass):
            raise TypeError(("metaclass conflict: the metaclass of "
                             "a derived class must be a (non-strict) subclass "
                             "of the metaclasses of all its bases"))
        if not issubclass(metaclass, base_mc):
            metaclass = base_mc

    return metaclass

