    if explicit_mc is not None:
        # Assume explicit_mc is the value of __metaclass__
        if isinstance(explicit_mc, type):
            explicit_mc_val = explicit_mc
        else:
            # If it's a type, we get its class
            explicit_mc_val = type(explicit_mc)

    # If an explicit metaclass is provided, it takes precedence
    if explicit_mc_val is not None:
        return explicit_mc_val

    # Return the metaclass of the base class or type by default
    if base_mc is not None:
        return base_mc

    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a type")
        for base in bases:
            base_metaclass = getattr(base, '__class__', None)
            if base_metaclass is not None:
                if not isinstance(base_metaclass, type):
                    raise TypeError("metaclass of base must be a type")
                if not (isinstance(explicit_mc, base_metaclass) or isinstance(base_metaclass, explicit_mc)):
                    raise TypeError("metaclasses are incompatible: %s vs %s" % (explicit_mc, base_metaclass))
        return explicit_mc
    else:
        # no explicit metaclass specified, use the most derived metaclass from bases
        metaclasses = [getattr(base, '__class__', None) for base in bases]
        # filter out None if any base doesn't have __class__ (unlikely)
        metaclasses = [mc for mc in metaclasses if mc is not None and isinstance(mc, type)]
        if not metaclasses:
            # default to type if no metaclasses found
            return type
        # find the most derived one
        most_derived = metaclasses[0]
        for mc in metaclasses[1:]:
            if isinstance(most_derived, mc):
                # mc is more derived or equal
                if not isinstance(mc, most_derived):
                    most_derived = mc
            elif isinstance(mc, most_derived):
                # most_derived is more derived or equal, keep it
                pass
            else:
                # incompatible metaclasses
                raise TypeError("metaclasses are incompatible: %s vs %s" % (most_derived, mc))
        return most_derived

