    if not hasattr(self, "in_expression"):
        raise AttributeError(
            "The in_expression attribute is not set. Please initialize it before calling _create_in_regex."
        )

    in_expression = self.in_expression
    if not isinstance(in_expression, str):
        raise TypeError("in_expression must be a string.")

    # Escape the expression for use in the regex
    escaped_expression = re.escape(in_expression)

    # The pattern assumes the expression is enclosed in parentheses within a larger identifier
    return re.compile(re.escape(r"(") + escaped_expression + re.escape(r")"))

