def isoparse(self, dt_str):
    # Handle bytes input
    if isinstance(dt_str, (bytes, bytearray)):
        dt_str = dt_str.decode('ascii')

    # Remove whitespace
    dt_str = dt_str.strip()
    if not dt_str:
        raise ValueError("Empty string")

    # Date part
    date_pattern = re.compile(
        r'(?P<year>\d{4})'
        r'(?:[-/](?P<month>\d{2}))?'
        r'(?:[-/](?P<day>\d{2}))?'
        r'|'
        r'(?P<year>\d{4})'
        r'[-W](?P<week>\d{2})'
        r'(?:[-](?P<weekday>\d{1}))?'
    )
    # Actually, let's use a stricter approach
    # Date part
    date_match = re.match(
        r'(?P<year>\d{4})'
        r'(?:'
        r'(?:(?P<sep1>[-])(?P<month>\d{2})?\.?(?:\.?(?P<day>\d{2})?)?)'
        r'|'
        r'(?:[-W](?P<week>\d{2})?(?:[-](?P<weekday>\d{1})?)?)'
        r')?',
        dt_str
    )

    # Simplified date parsing
    m = re.match(r'(\d{4})', dt_str)
    if not m:
        raise ValueError("Invalid ISO 8601 datetime")

    year = int(m.group(1))
    pos = 4
    month = day = None
    week = weekday = None

    # Check for year only
    if len(dt_str) == pos:
        # Just year
        month = 1
        day = 1
        time_str = None
        tz_str = None
        dt = datetime.datetime(year, month, day)
        return dt

    # Check for week-based date
    if pos < len(dt_str) and dt_str[pos] == 'W':
        # YYYY-Www or YYYYWww
        # Actually the format is YYYY-Www
        if pos < len(dt_str) and dt_str[pos] == 'W':
            pos += 1
            week_match = re.match(r'(\d{2})(?:-?(\d))?', dt_str[pos:])
            if not week_match:
                raise ValueError("Invalid ISO 8601 week")
            week = int(week_match.group(1))
            if week < 1 or week > 53:
                raise ValueError("Invalid week number")
            weekday = int(week_match.group(2)) if week_match.group(2) else 1
            pos += len(week_match.group(0))
            # Convert week date to actual date
            try:
                # Use date.isocalendar to reconstruct
                jan1 = datetime.date(year, 1, 1)
                iso_year, iso_week, iso_weekday = jan1.isocalendar()
                delta_weeks = week - iso_week
                date = jan1 + datetime.timedelta(weeks=delta_weeks, days=weekday-iso_weekday)
                month = date.month
                day = date.day
            except (ValueError, OverflowError):
                raise ValueError("Invalid ISO 8601 datetime")
        else:
            raise ValueError("Invalid ISO 8601 week")
    else:
        # YYYY-MM-DD or YYYYMMDD
        if pos < len(dt_str) and dt_str[pos] in '-/':
            # With separator
            pos += 1
            month_match = re.match(r'(\d{2})(?:[-/]?(\d{2})?)?', dt_str[pos:])
            if not month_match:
                raise ValueError("Invalid ISO 8601 date")
            month = int(month_match.group(1))
            if month < 1 or month > 12:
                raise ValueError("Invalid month")
            pos += len(month_match.group(1))
            if month_match.group(2):
                # There's a day
                day = int(month_match.group(2))
                pos += 1 + len(month_match.group(2))
                if day < 1 or day > 31:
                    raise ValueError("Invalid day")
            else:
                # YYYY-MM format
                day = 1
        else:
            # YYYYMMDD format
            month_day_match = re.match(r'(\d{2})(\d{2})?', dt_str[pos:])
            if not month_day_match:
                raise ValueError("Invalid ISO 8601 date")
            month = int(month_day_match.group(1))
            if month < 1 or month > 12:
                raise ValueError("Invalid month")
            pos += 2
            if month_day_match.group(2):
                day = int(month_day_match.group(2))
                pos += 2
                if day < 1 or day > 31:
                    raise ValueError("Invalid day")
            else:
                # YYYYMM format
