            except ValueError:
                raise ValueError("Invalid time")
            second = 0
        elif len(time_str) == 6:
            # hhmmss
            try:
                hour = int(time_str[:2])
                minute = int(time_str[2:4])
                second = int(time_str[4:6])
            except ValueError:
                raise ValueError("Invalid time")
        else:
            raise ValueError("Invalid time")

    # Validate time
    if hour == 24:
        if minute != 0 or second != 0 or microseconds != 0:
            raise ValueError("Invalid time: 24:00 must be midnight")
        hour = 0

    if hour > 24:
        raise ValueError("Invalid time")

    if hour > 23:
        raise ValueError("Invalid time")

    if minute > 59:
        raise ValueError("Invalid time")

    if second > 59:
        # Allow 60 for leap second? No, standard says 00-59
        raise ValueError("Invalid time")

    if microseconds > 999999:
        raise ValueError("Invalid microseconds")

    try:
        return datetime.datetime(year, month, day, hour, minute, second, microseconds, tzinfo=tz)
    except (ValueError, OverflowError, TypeError):
        raise ValueError("Invalid ISO 8601 datetime")

