        except UnicodeDecodeError as e:
            raise ParserError(f"Could not decode timestr: {e}") from e

    # Handle the case where default is a datetime object
    def has_default(default):
        return default is not None and isinstance(default, datetime.datetime)

    d = self._parser.parse(timestr, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)

    # If fuzzy_with_tokens, d is a tuple
