def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Convert public key to a PEM format if it isn't already
        if isinstance(public_key, str):
            pem_key = public_key
        else:
            from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat
            pem_key = public_key.public_bytes(Encoding.PEM, PublicFormat.SubjectPublicKeyInfo).decode('utf-8')

        # Encode the signature from base64 to bytes if it's a string
        import base64
        import binascii

        if isinstance(signature, str):
            try:
                sig_bytes = base64.b64decode(signature)
            except binascii.Error:
                # If it's not valid base64, it might be raw bytes encoded as string
                try:
                    sig_bytes = signature.encode('utf-8')
                except Exception:
                    sig_bytes = signature
        else:
            sig_bytes = signature

        # Verify the signature using the public key
        from cryptography.hazmat.primitives.asymmetric import utils,padding
        from cryptography.exceptions import InvalidSignature

        try:
            # Try loading the public key
            from cryptography.hazmat.primitives.serialization import load_pem_public_key
            pub_key = load_pem_public_key(pem_key.encode('utf-8'))
        except Exception as e:
            raise Exception(f"Invalid public key: {e}")

        # Verify signature
        try:
            pub_key.verify(
                sig_bytes,
                doc,
                # For RSA, we need appropriate padding; for EC, no padding needed
                # We'll assume the signature is over the exact doc bytes
                # This is a simplified verification - in practice, more complex
                # signature verification for XML signing would be used
                padding.PSS(mgf=utils.Prehashed(__import__('cryptography').hazmat.primitives.hashes.SHA256()), salt_length=32)
                if __import__('cryptography').hazmat.primitives.asymmetric.rsa.is_rsa_public_key(pub_key, Strict=isinstance(pub_key, __import__('cryptography').hazmat.primitives.asymmetric.rsa.RSAPublicKey)) else None
            )
            return True
        except InvalidSignature:
            return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    result = {}
    # Handle JSON format (with or without "webfinger" wrapper)
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # JSON format may be directly the webfinger object or wrapped
            data = data if isinstance(data.get("links", None), list) else data.get("webfinger", data)
            if isinstance(data, dict) and "links" in data:
                result["links"] = data["links"]
                subject = data.get("subject")
                if subject:
                    result["subject"] = subject
                return result
    except (json.JSONDecodeError, TypeError):
        pass
    # Handle XRD format
    data = None
    try:
        data = xmltodict.parse(document)
    except Exception:
        data = None
    if data is not None and isinstance(data, dict) and "XRD" in data:
        xrd = data.get("XRD", {})
        result_links = []
        aliased = xrd.get("Alias")
        if aliased:
            if not isinstance(aliased, list):
                aliased = [aliased]
            for item in aliased:
                if isinstance(item, dict) or (isinstance(item, str) or item is None):
                    entry = {
                        "link": item if isinstance(item, str) else item.get("$", item) if isinstance(item, dict) else None
                    }
                    # Preserve original attribute info
                    result_links.append(item if isinstance(item, dict) else {"link": item})
        props = xrd.get("Property")
        if props and isinstance(props, list):
            for prop in props:
                if isinstance(prop, dict):
                    value = prop.get("$")
                    link = prop.get("value")
                    if isinstance(value, dict):
                        link = value
                    result_links.append(link)
        if props and (not isinstance(props, list)):
            single = props.get("value", props)
            if isinstance(props, dict) and "value" not in props and isinstance(props.get("$"), dict):
                single = props["$"]
            if single is not None:
                result_links.append(single)
        result["links"] = result_links
        return result
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict

    from xml.etree import ElementTree
    # Try JSON first
    try:
        data = json.loads(document)
        # For JSON webfinger, the structure is like:
        # {
        #   "subject": "acct:user@domain.com",
        #   "aliases": ["https://domain.com/u/user"],
        #   "links": [
        #     {"rel": "lrdd", "href": "https://domain.com/.well-known/webfinger?..."},
        #     {"rel": "http://webfinger.net/rel/profile-page", "type": "text/html", "href": "https://domain.com/u/user"}
        #   ]
        # }
        # We need to extract the profile page URL or the second URL
        links = data.get("links", [])
        if links:
            # Find a link that is not lrdd
            for link in links:
                if link.get("rel") != "lrdd":
                    href = link.get("href")
                    if href:
                        return {
                            "diaspora_handle": data.get("subject", "").replace("acct:", ""),
                            "url": href
                        }
        # If no non-lrdd link, try aliases
        aliases = data.get("aliases", [])
        if aliases:
            return {
                "diaspora_handle": data.get("subject", "").replace("acct:", ""),
                "url": aliases[0]
            }
        # Fallback
        return {
            "diaspora_handle": data.get("subject", "").replace("acct:", ""),
            "url": ""
        }
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML)
    try:
        # XRD might need namespace handling
        root = ElementTree.fromstring(document)
        # Handle namespaces
        ns = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd/1.0'}
        # Find subject
        subject_elem = root.find('xrd:subject', ns)
        subject = subject_elem.text if subject_elem is not None else ""
        diaspora_handle = subject.replace("acct:", "") if subject else ""

        # Find links
        links_elem = root.find('xrd:links', ns)
        url = ""
        if links_elem is not None:
            for link in links_elem.findall('xrd:link', ns):
                rel = link.get('rel')
                # We want the profile page, usually 'http://webfinger.net/rel/profile-page'
                if rel == 'http://webfinger.net/rel/profile-page':
                    url = link.get('href', "")
                    break
                # Or just take the first link that is not lrdd
                elif rel != 'lrdd' and not url:
                    url = link.get('href', "")

        return {
            "diaspora_handle": diaspora_handle,
            "url": url
        }
    except ElementTree.ParseError:
        raise ValueError("Invalid webfinger document: not valid JSON or XRD")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first (new format)
    try:
        data = json.loads(document)
        # Check if it looks like webfinger JSON
        if isinstance(data, dict) and 'links' in data:
            result = {}
            result['links'] = data.get('links', [])
            for field in ['subject', 'alias', 'properties']:
                if field in data:
                    result[field] = data[field]
            return result
    except json.JSONDecodeError:
        pass

    # Try XML XRD format (old format)
    try:
        root = ET.fromstring(document)
        # XRD namespace
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

        result = {'links': []}

        # Parse rel and other attributes and children
        for link in root.findall('xrd:Link', ns):
            link_data = {}
            for key, value in link.attrib.items():
                link_data[key] = value

            # Also get nested elements if any
            for child in link:
                tag = child.tag.split('{')[-1] if '}' in child.tag else child.tag
                link_data[tag] = child.text

            result['links'].append(link_data)

        # Parse xrd:Property elements
        result['properties'] = []
        for prop in root.findall('xrd:Property', ns):
            prop_data = {}
            for key, value in prop.attrib.items():
                prop_data[key] = value
            if prop.text:
                prop_data['value'] = prop.text.strip()
            result['properties'].append(prop_data)

        # Parse xrd:Alias
        aliases = [alias.text.strip() for alias in root.findall('xrd:Alias', ns) if alias.text]
        result['aliases'] = aliases

        # Find xrd:Subject
        subject_elem = root.find('xrd:Subject', ns)
        if subject_elem is not None and subject_elem.text:
            result['subject'] = subject_elem.text.strip()

        # Remove empty properties key if no properties
        if not result['properties']:
            del result['properties']

        return result

    except ET.ParseError:
        raise ValueError("Input document is not valid JSON or XML XRD")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    from typing import Optional

    import requests
    if not handle or not isinstance(handle, str):
        return None
    try:
        url = f"https://{handle}/.well-known/webfinger?resource=acct:{handle}"
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            return response.text
    except Exception:
        pass
    return None

def retrieve_and_parse_diasporwebfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import json

    # Construct the webfinger URL
    # Diaspora webfinger typically uses the URI format:
    # https://<host>/.well-known/webfinger?resource=acct:<user>
    # The handle argument is often passed as e.g. "@user@remote.host.com"

    if not isinstance(handle, str) or not handle:
        return {}

    # Sanitize the handle
    # A handle might be "@user@domain" or "user@domain"
    sanitized_handle = handle.strip()
    if sanitized_handle.startswith('@'):
        sanitized_handle = sanitized_handle[1:]

    if '@' not in sanitized_handle:
        return {}

    split_handle = sanitized_handle.split('@')
    if len(split_handle) != 2:
        return {}

    user, domain = split_handle

    # URL encode the resource part
    resource = f"acct:{user}@{domain}"
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"

    try:
        request = urllib.request.Request(url)
        response = urllib.request.urlopen(request, timeout=10)

        if response.getcode() != 200:
            return {}

        data = response.read().decode('utf-8')
        return json.loads(data)

    except Exception:
        return {}

