def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Assume that self has a method get_parser and an attribute parsers
    if not hasattr(self, 'parsers') or command_name not in self.parsers:
        raise ValueError(f"Command {command_name} not found in parsers")

    parser = self.parsers[command_name]

    # Get the list of all options
    option_specs = []
    for action in parser._actions:
        if hasattr(action, 'option_strings'):
            for option_string in action.option_strings:
                option_specs.append({
                    'name': option_string,
                    'dest': action.dest,
                    'default': action.default,
                    'help': action.help
                })
    return option_specs

