def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    try:
        for option in options_spec:
            if not hasattr(option, 'required_when') or option.required_when is None:
                continue

            # Extract the condition
            condition_attr = option.required_when
            if isinstance(condition_attr, str):
                # It's a string attribute name from args
                condition = getattr(args, condition_attr, None)
            else:
                # It's a lambda or callable
                try:
                    condition = option.required_when(args, command_name)
                except TypeError:
                    # Maybe it takes only args
                    try:
                        condition = option.required_when(args)
                    except Exception:
                        condition = False

            if condition:
                # Add the option name to required list
                # Assume 'name' is the standard attribute for the argument name
                if hasattr(option, 'name'):
                    required_args.append(option.name)
                elif hasattr(option, 'get_name'):
                    required_args.append(option.get_name())
    except Exception:
        # Silently fail or log, but return the current state
        pass

    return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_when_args = []
    for option in options_spec:
        if not isinstance(option, dict):
            continue
        option_name = option.get('name')
        if option_name is None:
            continue
        required_when = option.get('required_when')
        if not required_when:
            continue
        # required_when is a list of (pattern, value) pairs
        matched = False
        for pattern, value in required_when:
            if args.get(pattern) == value:
                matched = True
                break
        if matched:
            required_when_args.append(option_name)
    return required_when_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    if not command_name:
        raise ValueError("command_name must be provided")
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple")

    conditionally_required_args = []
    for option in options_spec:
        if not isinstance(option, dict):
            raise TypeError("Each entry in options_spec must be a dictionary")
        if 'required_when' not in option:
            continue
        condition = option['required_when']
        if not isinstance(condition, callable):
            raise TypeError("required_when must be a callable")
        if condition(self, command_name, args):
            name = option.get('name')
            if name is not None:
                conditionally_required_args.append(name)
    return conditionally_required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    arg_map = self._args if hasattr(self, '_args') else {}

    for option in options_spec:
        if option.get('required_when'):
            condition = option['required_when']
            # Evaluate condition to check if it matches
            if self._eval_condition(condition, command_name, options_spec, args):
                required_args.append(option['name'])
    return required_args

