def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        valid_args = []
        min_value = getattr(self, 'min_value', None)
        max_value = getattr(self, 'max_value', None)
        for arg in args:
            if min_value is not None and max_value is not None:
                if arg < min_value or arg > max_value:
                    raise ValueError(f"Argument {arg} is out of range [min_value, max_value]")
            valid_args.append(arg)
        return valid_args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'min_values') or not hasattr(self, 'max_values'):
        raise ValueError("Object has not defined 'min_values' and 'max_values' attributes.")

    for arg_name in args:
        if arg_name in self.__dict__:
            value = getattr(self, arg_name)
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value of {arg_name} must be a number.")
            min_val = self.min_values.get(arg_name)
            max_val = self.max_values.get(arg_name)

            if min_val is not None and value < min_val:
                raise ValueError(f"Value of {arg_name} ({value}) is less than the minimum value ({min_val}).")
            if max_val is not None and value > max_val:
                raise ValueError(f"Value of {arg_name} ({value}) is greater than the maximum value ({max_val}).")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Extract values if they are dictionaries, otherwise consider them directly as values
    if isinstance(args, dict):
        values = list(args.values())
    elif isinstance(args, (list, tuple)):
        values = args
    else:
        # Assume args is a single value for this case
        values = [args]

    for key, value in (args.items() if isinstance(args, dict) else enumerate(values)):
        min_val = getattr(self, '_min' + str(key).upper() if isinstance(args, dict) else '_MIN_VALUE', None)
        max_val = getattr(self, '_max' + str(key).upper() if isinstance(args, dict) else '_MAX_VALUE', None)

    # If 'args' is a dict, validate each key-value pair using dynamic attribute names
    if isinstance(args, dict):
        for key, value in args.items():
            min_attr = '_min_' + key
            max_attr = '_max_' + key
            min_val = getattr(self, min_attr, None)
            max_val = getattr(self, max_attr, None)
            if min_val is not None and value < min_val:
                raise ValueError(f"Value of argument '{key}' must be at least {min_val}.")
            if max_val is not None and value > max_val:
                raise ValueError(f"Value of argument '{key}' must be at most {max_val}.")
    # If 'args' is not a dict, assume a generic _min_value and _max_value
    else:
        values = args if isinstance(args, (list, tuple)) else [args]

        min_val = getattr(self, '_min_value', None)
        max_val = getattr(self, '_max_value', None)

        for val in values:
            if min_val is not None and val < min_val:
                raise ValueError(f"Value {val} must be at least {min_val}.")
            if max_val is not None and val > max_val:
                raise ValueError(f"Value {val} must be at most {max_val}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for name, value in args.items():
        if name in self._min_values:
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                min_val = self._min_values[name]
                max_val = self._max_values.get(name)
                if value < min_val:
                    raise ValueError(
                        f"Argument '{name}' must be at least {min_val}, got {value}"
                    )
                if max_val is not None and value > max_val:
                    raise ValueError(
                        f"Argument '{name}' must be at most {max_val}, got {value}"
                    )
            else:
                raise TypeError(
                    f"Argument '{name}' must be an integer or float, got {type(value)}"
                )
        elif name in self._max_values:
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                max_val = self._max_values[name]
                if value > max_val:
                    raise ValueError(
                        f"Argument '{name}' must be at most {max_val}, got {value}"
                    )
            else:
                raise TypeError(
                    f"Argument '{name}' must be an integer or float, got {type(value)}"
                )

