def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    if args is None or not isinstance(args, list):
        return control_args, nested_args
    for arg in args:
        if not isinstance(arg, dict) or "role" not in arg:
            continue
        arg_name = arg.get("name")
        role_type = arg.get("role", "")
        option = arg.get("option", "")
        value = arg.get("value")
        if not arg_name:
            continue
        # Handle unset values with defaults
        if value is None:
            default = arg.get("default", None)
            if default is not None:
                value = default
        key = f"{arg_name}__{role_type}__{option}" if option else f"{arg_name}__{role_type}"
        if role_type.lower() == "control":
            control_args[key] = value
        elif role_type.lower() in ["nested", "custom"]:
            nested_args[key] = value

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        # Check if the argument is a control argument
        if self.is_control_arg(arg):
            control_args[arg] = True
        else:
            nested_args[arg] = True

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    for arg in args:
        if isinstance(arg, tuple) and len(arg) == 2:
            key, value = arg
        else:
            key, value = arg, None
        if key.startswith('--'):
            key = key[2:]; # Remove leading --
        if 'custom' in key or 'control' in key:
            control_args[key] = value
        else:
            nested_args[key] = value
    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    if not args or not isinstance(args, (list, tuple)):
        return control_args, nested_args

    for arg in args:
        if not isinstance(arg, str) or not arg.startswith('-'):
            # Handle unexpected argument formats gracefully by ignoring them.
            continue

        # Remove leading dashes for easier processing
        key = arg.lstrip('-')

        # Identifying control arguments based on a defined set
        if key in self.control_args_keys:
            control_args[key] = True
        elif key in self.custom_args_keys:
            # Custom arguments are tracked but returned as part of nested_args
            # as per the return type specification (control_args, nested_args)
            custom_args[key] = True
        else:
            # Standard nested arguments get handled here
            # Determine if it's a key-value pair or a boolean flag
