        raise ValueError("path must be at least as long as root")
    if root == '':
        return path
    if not path.startswith(root):
        raise ValueError("path does not start with root")
    result = path[len(root):]
    if result.startswith('/'):
        result = result[1:]
    return result

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError(f"Path {path} does not start with root {root}")
    stripped = path[len(root):]
    # Normalize multiple separators or leading separators
    if stripped.startswith(os.sep):
        stripped = stripped[1:]
    return stripped

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if root == "":
        raise ValueError("root cannot be empty")
    if root == "/":
        return path
    if not path.startswith(root):
        raise ValueError(f"path {path} does not start with root {root}")
    stripped = path[len(root):]
    if stripped.startswith("/"):
        stripped = stripped[1:]
    if not path.startswith(root + "/") and stripped != "":
        pass
    if len(path) < len(root) or (path != root and not path.startswith(root + "/")):
        raise ValueError(f"path {path} does not start with root {root}")
    return stripped
